const b = $input.first().json.body || {};
const clean = (v, max) => String(v ?? '').trim().slice(0, max);
if (b.company_site) throw new Error('Rejected: honeypot field was filled');
const name = clean(b.name, 120);
const email = clean(b.email, 160);
const type = clean(b.type, 60) || 'Not specified';
const message = clean(b.message, 4000);
if (name.length < 2) throw new Error('Rejected: name missing');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) throw new Error('Rejected: invalid email');
if (message.length < 10) throw new Error('Rejected: brief too short');
return [{ json: { name, email, type, message, source: clean(b.source, 120), sentAt: clean(b.sentAt, 40) } }];

